import * as React from 'react';
import type { ButtonProps } from '@oods/components-react';
import { Button } from '@/registry/new-york-v4/ui/button';

export const OodsButton = React.forwardRef<HTMLButtonElement, ButtonProps>(function OodsButton(
  { content, children, intent = 'neutral', size = 'md', type, asChild = false, className, onClick, onActivate, ...props }, ref,
) {
  const variant = intent === 'danger' || intent === 'destructive' ? 'destructive'
    : intent === 'primary' ? 'default'
    : intent === 'neutral' ? 'secondary'
    : intent === 'success' || intent === 'warning' ? 'secondary' : intent;
  // Keep normal-size destructive text readable using the team's solid tokens in both themes.
  const destructiveClass = variant === 'destructive' ? 'bg-destructive text-background hover:bg-destructive dark:bg-destructive dark:hover:bg-destructive' : undefined;
  return <Button {...props} ref={ref} className={[destructiveClass, className].filter(Boolean).join(' ')} variant={variant} size={size === 'md' ? 'default' : size === 'xs' ? 'sm' : size}
    asChild={asChild} {...(asChild ? {} : { type: type ?? 'button' })} data-oods-component={undefined} data-oods-adapter="Button"
    data-intent={intent} onClick={event => { onClick?.(event); if (!event.defaultPrevented) onActivate?.(event); }}>
    {children ?? content}
  </Button>;
});

import * as React from 'react';
import type { CardProps } from '@oods/components-react';
import { Card } from '@/registry/new-york-v4/ui/card';

export const OodsCard = React.forwardRef<HTMLElement, CardProps>(function OodsCard(
  { as = 'div', elevated = false, className, children, ...props }, ref,
) {
  const classes = ['px-4', elevated ? 'shadow-lg' : 'shadow-none', className].filter(Boolean).join(' ');
  if (as === 'div') return <Card {...props} ref={ref as React.Ref<HTMLDivElement>} className={classes} data-oods-component={undefined} data-oods-adapter="Card">{children}</Card>;
  const Tag = as;
  return <Tag {...props} ref={ref} data-oods-component={undefined} data-oods-adapter="Card"><Card className={classes}>{children}</Card></Tag>;
});

import * as React from 'react';
import type { StatusBadgeProps } from '@oods/components-react';
import { getStatusPresentation, resolveStatusIcon, statusIconMarkup } from '@oods/component-contracts';
import { Badge } from '@/registry/new-york-v4/ui/badge';

export const OodsStatusBadge = React.forwardRef<HTMLSpanElement, StatusBadgeProps>(function OodsStatusBadge(
  { status, value, label, children, content, domain = 'subscription', tone, emphasis = 'subtle', variant,
    showIcon = true, icon, iconPosition = 'start', title, field, statusField, domainField, readOnly, compact,
    'aria-label': ariaLabel, className, ...props }, ref,
) {
  void [field, statusField, domainField, readOnly, compact];
  const state = status ?? value ?? 'unknown';
  const presentation = getStatusPresentation(domain, state);
  const resolvedTone = tone && tone !== 'lifecycle' ? tone : presentation.tone;
  const destructive = resolvedTone === 'critical' || resolvedTone === 'danger';
  const solid = variant === 'solid' || emphasis === 'solid';
  const name = resolveStatusIcon(presentation.iconName);
  const mark = showIcon ? icon ?? (name ? <span aria-hidden="true" dangerouslySetInnerHTML={{ __html: statusIconMarkup(name) }} /> : null) : null;
  const destructiveClass = destructive ? 'bg-destructive text-background dark:bg-destructive [a]:hover:bg-destructive' : undefined;
  return <Badge {...props} role={props.role ?? 'status'} ref={ref} className={[destructiveClass, className].filter(Boolean).join(' ')} variant={destructive ? 'destructive' : solid ? 'default' : 'secondary'}
    data-oods-component={undefined} data-oods-adapter="StatusBadge" data-status={state} data-domain={domain} data-tone={resolvedTone}
    title={title ?? presentation.description} aria-label={ariaLabel ?? label ?? `Status: ${presentation.label}`}>
    {iconPosition === 'start' ? mark : null}{children ?? content ?? presentation.label}{iconPosition === 'end' ? mark : null}
  </Badge>;
});

import * as React from 'react';
import type { TabsProps } from '@oods/components-react';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/registry/new-york-v4/ui/tabs';

export const OodsTabs = React.forwardRef<HTMLDivElement, TabsProps>(function OodsTabs(
  { items, selectedId, defaultSelectedId, size = 'md', overflowLabel, ariaLabel, onChange, onUpdate, dir, 'aria-label': nativeLabel, ...props }, ref,
) {
  void overflowLabel; // This adapter scrolls the tab list; it has no overflow menu.
  const [local, setLocal] = React.useState(defaultSelectedId ?? items.find(item => !item.disabled && !item.isDisabled)?.id);
  const selected = selectedId ?? local;
  const notified = React.useRef(selected); notified.current = selected;
  const select = (id: string) => {
    if (id === notified.current) return;
    notified.current = id;
    if (selectedId === undefined) setLocal(id);
    onChange?.(id); onUpdate?.(id);
  };
  return <Tabs {...props} ref={ref} value={selected} defaultValue={defaultSelectedId} dir={dir === 'ltr' || dir === 'rtl' ? dir : undefined}
    data-oods-component={undefined} data-oods-adapter="Tabs" data-size={size} onValueChange={select}>
    <div className="max-w-full overflow-x-auto"><TabsList aria-label={ariaLabel ?? nativeLabel}>
      {items.map(item => <TabsTrigger key={item.id} data-tab-id={item.id} value={item.id} disabled={item.disabled || item.isDisabled} onFocus={item.disabled || item.isDisabled ? undefined : () => select(item.id)}
        className={size === 'sm' ? 'text-xs' : size === 'lg' ? 'text-base' : undefined}>{item.label}</TabsTrigger>)}
    </TabsList></div>
    {items.map(item => <TabsContent key={item.id} value={item.id}>{item.panel}</TabsContent>)}
  </Tabs>;
});

import * as React from 'react';
import type { SelectProps } from '@oods/components-react';
import { Label } from '@/registry/new-york-v4/ui/label';
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from '@/registry/new-york-v4/ui/select';

export const OodsSelect = React.forwardRef<HTMLSelectElement, SelectProps>(function OodsSelect(
  { id, label, options = [], value, defaultValue, placeholder, required, disabled, name, help, description, validation,
    onChange, onValueChange, onUpdate, className, style, selectClassName, selectStyle, density, requiredIndicator,
    children, 'aria-describedby': describedBy, 'aria-label': ariaLabel }, ref,
) {
  const native = React.useRef<HTMLSelectElement>(null);
  React.useImperativeHandle(ref, () => native.current!);
  const [local, setLocal] = React.useState(String(defaultValue ?? ''));
  const selected = value === undefined ? local : String(value);
  const empty = '__oods_empty_option__';
  const details = help ?? description;
  const helpId = `${id}-help`, validationId = validation?.id ?? `${id}-validation`;
  const descriptions = [describedBy, details ? helpId : '', validation?.message ? validationId : ''].filter(Boolean).join(' ') || undefined;
  // Keep a real native change event for generated OODS handlers and native form submission.
  const change = (next: string | null) => {
    if (!native.current) return;
    native.current.value = next === empty ? '' : next ?? '';
    native.current.dispatchEvent(new Event('change', { bubbles: true }));
  };
  return <div className={className} style={style} data-oods-component={undefined} data-oods-adapter="Select">
    <Label htmlFor={`${id}-control`}>{label}{required && requiredIndicator !== false ? <span aria-hidden="true"> *</span> : null}</Label>
    <select id={id} ref={native} name={name} value={selected} disabled={disabled} tabIndex={-1} aria-hidden="true" style={{ display: 'none' }}
      onChange={event => { onChange?.(event); if (!event.defaultPrevented) { const next = event.currentTarget.value; if (value === undefined) setLocal(next); onValueChange?.(next); onUpdate?.(next); } }}>
      <option value="">{placeholder}</option>{options.map(option => <option key={option.value} value={option.value} disabled={option.disabled}>{option.label}</option>)}
    </select>
    <Select value={selected || (options.some(option => option.value === '') ? empty : '')} disabled={disabled} required={required} onValueChange={change}>
      <SelectTrigger id={`${id}-control`} aria-label={ariaLabel} aria-describedby={descriptions} aria-invalid={validation?.state === 'error' || undefined}
        size={density === 'compact' ? 'sm' : 'default'} className={selectClassName} style={selectStyle}><SelectValue placeholder={placeholder}>{options.find(option => String(option.value) === selected)?.label ?? placeholder}</SelectValue></SelectTrigger>
      <SelectContent>{children ?? options.map(option => <SelectItem key={option.value} value={option.value || empty} disabled={option.disabled}>{option.label}</SelectItem>)}</SelectContent>
    </Select>
    {details ? <p id={helpId} className="text-sm text-muted-foreground">{details}</p> : null}
    {validation?.message ? <p id={validationId} role={validation.state === 'error' ? 'alert' : undefined}>{validation.message}</p> : null}
  </div>;
});

import * as React from 'react';
import type { SearchInputProps } from '@oods/components-react';
import { Input } from '@/registry/new-york-v4/ui/input';
import { Label } from '@/registry/new-york-v4/ui/label';
import { Button } from '@/registry/new-york-v4/ui/button';

export const OodsSearchInput = React.forwardRef<HTMLInputElement, SearchInputProps>(function OodsSearchInput(
  { id, label = 'Search', value, defaultValue = '', placeholder = 'Search…', clearable = true, debounceMs, debounce,
    minQueryLength = 0, field, placeholderParameter, debounceParameter, minQueryLengthParameter, clearableParameter,
    onChange, onValueChange, onUpdate, onSearch, onClear, onKeyDown, className, disabled, ...props }, ref,
) {
  void [field, placeholderParameter, debounceParameter, minQueryLengthParameter, clearableParameter];
  const instance = React.useId();
  const inputId = id ?? `oods-search-${instance.replaceAll(':', '')}`;
  const [local, setLocal] = React.useState(defaultValue);
  const current = value ?? local;
  const timer = React.useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  React.useEffect(() => () => clearTimeout(timer.current), []);
  const update = (next: string) => {
    if (value === undefined) setLocal(next);
    clearTimeout(timer.current);
    const emit = () => { if (next.length >= minQueryLength || next === '') { onValueChange?.(next); onUpdate?.(next); onSearch?.(next); } };
    const delay = Math.max(0, debounceMs ?? debounce ?? 0);
    if (delay) timer.current = setTimeout(emit, delay); else emit();
  };
  const clear = () => { onClear?.(); update(''); };
  return <div role="search" aria-label={label} className={className} data-oods-component={undefined} data-oods-adapter="SearchInput">
    <Label htmlFor={inputId}>{label}</Label><div className="flex gap-2">
      <Input {...props} ref={ref} id={inputId} type="search" placeholder={placeholder} disabled={disabled} value={current}
        onChange={event => { onChange?.(event); if (!event.defaultPrevented) update(event.currentTarget.value); }}
        onKeyDown={event => { onKeyDown?.(event); if (!event.defaultPrevented && event.key === 'Escape' && current) clear(); }} />
      {clearable && current ? <Button type="button" variant="ghost" disabled={disabled} aria-label="Clear search" onClick={clear}>×</Button> : null}
    </div>
  </div>;
});

import * as React from 'react';
import type { PaginationBarProps } from '@oods/components-react';
import { Pagination, PaginationContent, PaginationItem, PaginationLink, PaginationPrevious, PaginationNext, PaginationEllipsis } from '@/registry/new-york-v4/ui/pagination';

export const OodsPaginationBar = React.forwardRef<HTMLElement, PaginationBarProps>(function OodsPaginationBar(
  { page = 1, pageSize = 25, totalItems = 0, totalPages: supplied, pageSizeOptions = [10, 25, 50, 100],
    showPageSizeSelector = false, showGotoPage = false, showItemRange = true, onPageChange, onPageSizeChange, onChange, onUpdate,
    pageField, pageSizeField, totalItemsField, totalPagesField, pageSizeOptionsParameter, showPageSizeSelectorParameter,
    showGotoPageParameter, showItemRangeParameter, className, 'aria-label': label = 'Pagination', ...props }, ref,
) {
  void [pageField, pageSizeField, totalItemsField, totalPagesField, pageSizeOptionsParameter, showPageSizeSelectorParameter, showGotoPageParameter, showItemRangeParameter];
  const size = Number.isFinite(pageSize) && pageSize > 0 ? Math.floor(pageSize) : 25;
  const count = Math.max(0, Math.floor(supplied ?? Math.ceil(Math.max(0, totalItems) / size)));
  const current = count ? Math.max(1, Math.min(Math.floor(page), count)) : 1;
  const go = (next: number) => { const target = Math.max(1, Math.min(Math.floor(next), count)); if (count && Number.isFinite(target) && target !== current) { onPageChange?.(target); onChange?.(target); onUpdate?.(target); } };
  const numbers = count <= 7 ? Array.from({ length: count }, (_, i) => i + 1) : [...new Set([1, current - 1, current, current + 1, count])].filter(n => n >= 1 && n <= count).sort((a, b) => a - b);
  const pages: Array<number | string> = [];
  numbers.forEach((n, index) => { if (index && n - numbers[index - 1] > 1) pages.push(`gap-${n}`); pages.push(n); });
  const link = (target: number, disabled = false) => ({ href: '#', role: 'link' as const, 'aria-disabled': disabled || undefined, tabIndex: disabled ? -1 : 0, onClick: (event: React.MouseEvent<HTMLAnchorElement>) => { event.preventDefault(); if (!disabled) go(target); } });
  return <Pagination {...props} ref={ref} aria-label={label} data-oods-component={undefined} data-oods-adapter="PaginationBar" className={['flex-wrap items-center gap-3', className].filter(Boolean).join(' ')}>
    {showItemRange ? <><span>{`${totalItems} ${totalItems === 1 ? 'record' : 'records'}`}</span>{totalItems > 0 && count > 1 ? <span>{`Showing ${(current - 1) * size + 1}–${Math.min(current * size, totalItems)} of ${totalItems}`}</span> : null}</> : null}
    {count > 1 ? <><PaginationContent>
      <PaginationItem><PaginationPrevious {...link(current - 1, current <= 1)} aria-label="Previous page" /></PaginationItem>
      {pages.map(n => <PaginationItem key={n}>{typeof n === 'number' ? <PaginationLink {...link(n)} isActive={n === current} aria-label={`Page ${n}`}>{n}</PaginationLink> : <PaginationEllipsis />}</PaginationItem>)}
      <PaginationItem><PaginationNext {...link(current + 1, current >= count)} aria-label="Next page" /></PaginationItem>
    </PaginationContent><span>{`Page ${current} of ${count}`}</span></> : null}
    {showPageSizeSelector ? <label>Items per page<select aria-label="Items per page" value={size} onChange={event => onPageSizeChange?.(Number(event.currentTarget.value))}>{pageSizeOptions.map(option => <option key={option} value={option}>{option}</option>)}</select></label> : null}
    {showGotoPage ? <label>Go to page<input type="number" min={1} max={Math.max(1, count)} defaultValue={current} onKeyDown={event => { if (event.key === 'Enter') go(Number(event.currentTarget.value)); }} /></label> : null}
  </Pagination>;
});

import * as React from 'react';
import type { BannerProps } from '@oods/components-react';
import { getStatusPresentation, resolveStatusIcon, statusIconMarkup } from '@oods/component-contracts';
import { Alert, AlertTitle, AlertDescription } from '@/registry/new-york-v4/ui/alert';
import { Button } from '@/registry/new-york-v4/ui/button';

export const OodsBanner = React.forwardRef<HTMLDivElement, BannerProps>(function OodsBanner(
  { title, detail, description, content, children, status, domain = 'subscription', tone, emphasis = 'subtle', icon,
    showIcon, actions, onDismiss, dismissLabel = 'Dismiss notification', className, ...props }, ref,
) {
  const presentation = status ? getStatusPresentation(domain, status) : undefined;
  const resolvedTone = tone ?? presentation?.tone ?? 'neutral';
  const critical = resolvedTone === 'critical' || resolvedTone === 'danger';
  const heading = title ?? presentation?.label ?? status;
  const body = detail ?? description ?? children ?? content ?? presentation?.description;
  const name = resolveStatusIcon(presentation?.iconName);
  const mark = icon ?? (name ? <span aria-hidden="true" dangerouslySetInnerHTML={{ __html: statusIconMarkup(name) }} /> : null);
  const destructiveClass = critical ? 'bg-destructive text-background *:data-[slot=alert-description]:text-inherit' : undefined;
  return <Alert {...props} ref={ref} className={[destructiveClass, className].filter(Boolean).join(' ')} variant={critical ? 'destructive' : 'default'} role={critical ? 'alert' : 'status'}
    aria-live={critical ? 'assertive' : 'polite'} data-oods-component={undefined} data-oods-adapter="Banner" data-tone={resolvedTone} data-emphasis={emphasis}>
    {(showIcon ?? Boolean(mark)) ? mark : null}{heading ? <AlertTitle>{heading}</AlertTitle> : null}
    {body ? <AlertDescription>{body}</AlertDescription> : null}{actions}
    {onDismiss ? <Button type="button" variant="ghost" aria-label={dismissLabel} onClick={onDismiss}>×</Button> : null}
  </Alert>;
});

import * as React from 'react';
import type { InputProps } from '@oods/components-react';
import { dateTimeInputValue } from '@oods/component-contracts';
import { Input } from '@/registry/new-york-v4/ui/input';
import { Label } from '@/registry/new-york-v4/ui/label';

export const OodsInput = React.forwardRef<HTMLInputElement, InputProps>(function OodsInput(
  { id, label, help, description, validation, density = 'comfortable', requiredIndicator, className, style,
    inputClassName, inputStyle, onChange, onValueChange, onUpdate, required, type = 'text', 'aria-describedby': describedBy, ...props }, ref,
) {
  if (type === 'datetime-local') {
    if (props.value !== undefined) props.value = dateTimeInputValue(props.value);
    if (props.defaultValue !== undefined) props.defaultValue = dateTimeInputValue(props.defaultValue);
  }
  const details = help ?? description;
  const validationId = validation?.id ?? `${id}-validation`;
  const descriptions = [describedBy, details ? `${id}-description` : '', validation?.message ? validationId : ''].filter(Boolean).join(' ') || undefined;
  return <div className={className} style={style} data-density={density} data-validation-state={validation?.state} data-oods-component={undefined} data-oods-adapter="Input">
    <Label htmlFor={id}>{label}{required && requiredIndicator !== null ? requiredIndicator ?? <span aria-hidden="true"> *</span> : null}</Label>
    <Input {...props} ref={ref} id={id} type={type} required={required} className={[density === 'compact' ? 'py-1' : '', inputClassName].filter(Boolean).join(' ')} style={inputStyle}
      data-oods-component={undefined} data-validation-state={validation?.state} aria-describedby={descriptions} aria-invalid={props['aria-invalid'] ?? (validation?.state === 'error' || undefined)}
      onChange={event => { onChange?.(event); if (!event.defaultPrevented) { onValueChange?.(event.currentTarget.value); onUpdate?.(event.currentTarget.value); } }} />
    {details ? <p id={`${id}-description`} className="text-sm text-muted-foreground">{details}</p> : null}
    {validation?.message ? <p id={validationId} role={validation.state === 'error' ? 'alert' : 'status'} aria-live={validation.state === 'error' ? 'assertive' : 'polite'}>{validation.message}</p> : null}
  </div>;
});

