import * as React from 'react';
import type { CheckboxProps } from '@oods/components-react';
import { Checkbox } from '@/registry/new-york-v4/ui/checkbox';
import { Label } from '@/registry/new-york-v4/ui/label';

export const OodsCheckbox = React.forwardRef<HTMLInputElement, CheckboxProps>(function OodsCheckbox(
  { id, label, help, description, validation, density = 'comfortable', requiredIndicator, className, style,
    checkboxClassName, checkboxStyle, onChange, onCheckedChange, onUpdate, required, checked, defaultChecked,
    disabled, readOnly, 'aria-describedby': describedBy, 'aria-label': ariaLabel, ...props }, ref,
) {
  const native = React.useRef<HTMLInputElement>(null);
  React.useImperativeHandle(ref, () => native.current!);
  const [local, setLocal] = React.useState(defaultChecked ?? false);
  const selected = checked ?? local;
  const resetting = React.useRef(false);
  React.useEffect(() => {
    const input = native.current;
    const form = input?.form;
    if (!input || !form) return;
    const reset = (event: Event) => {
      // Team checkbox primitives also observe reset. Preserve native reset's lack of change events.
      resetting.current = true;
      queueMicrotask(() => {
        resetting.current = false;
        if (!event.defaultPrevented && checked === undefined) {
          // The browser resets the property without running React's native value setter.
          input.checked = input.checked;
          setLocal(input.checked);
        }
      });
    };
    form.addEventListener('reset', reset, true);
    return () => form.removeEventListener('reset', reset, true);
  }, [checked, props.form]);
  const details = help ?? description;
  const validationId = validation?.id ?? `${id}-validation`;
  const descriptions = [describedBy, details ? `${id}-description` : '', validation?.message ? validationId : ''].filter(Boolean).join(' ') || undefined;
  return <div className={className} style={style} data-density={density} data-validation-state={validation?.state} data-oods-component={undefined} data-oods-adapter="Checkbox">
    <input {...props} id={id} ref={native} type="checkbox" checked={checked} defaultChecked={checked === undefined ? defaultChecked : undefined} disabled={disabled} readOnly={readOnly} required={required}
      className="sr-only" tabIndex={-1} aria-hidden="true" data-oods-component={undefined}
      onChange={event => { onChange?.(event); if (!event.defaultPrevented) { const next = event.currentTarget.checked; if (checked === undefined) setLocal(next); onCheckedChange?.(next); onUpdate?.(next); } }} />
    <div className="flex items-center gap-2">
      <Checkbox id={`${id}-control`} checked={selected} disabled={disabled} required={required} aria-readonly={readOnly || undefined}
        className={checkboxClassName} style={checkboxStyle} aria-label={ariaLabel} aria-describedby={descriptions} aria-invalid={props['aria-invalid'] ?? (validation?.state === 'error' || undefined)}
        onCheckedChange={() => { if (!readOnly && !resetting.current) native.current?.click(); }} />
      <Label htmlFor={`${id}-control`}>{label}{required && requiredIndicator !== null ? requiredIndicator ?? <span aria-hidden="true"> *</span> : null}</Label>
    </div>
    {details ? <p id={`${id}-description`} className="text-sm text-muted-foreground">{details}</p> : null}
    {validation?.message ? <p id={validationId} role={validation.state === 'error' ? 'alert' : 'status'} aria-live={validation.state === 'error' ? 'assertive' : 'polite'}>{validation.message}</p> : null}
  </div>;
});

import * as React from 'react';
import type { DatePickerProps } from '@oods/components-react';
import { Input } from '@/registry/new-york-v4/ui/input';
import { Label } from '@/registry/new-york-v4/ui/label';
import { Button } from '@/registry/new-york-v4/ui/button';
import { Calendar } from '@/registry/new-york-v4/ui/calendar';
import { Popover, PopoverTrigger, PopoverContent } from '@/registry/new-york-v4/ui/popover';

const dateValue = (date: Date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
const parseDate = (value: unknown) => {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return undefined;
  const date = new Date(`${value}T12:00:00`);
  return Number.isFinite(date.getTime()) && dateValue(date) === value ? date : undefined;
};

export const OodsDatePicker = React.forwardRef<HTMLInputElement, DatePickerProps>(function OodsDatePicker(
  { id, label, help, description, validation, density = 'comfortable', requiredIndicator, className, style,
    inputClassName, inputStyle, pickerClassName, pickerStyle, onChange, onValueChange, onUpdate, required,
    value, defaultValue, disabled, readOnly, min, max, step, 'aria-describedby': describedBy, ...props }, ref,
) {
  const native = React.useRef<HTMLInputElement>(null);
  React.useImperativeHandle(ref, () => native.current!);
  const [local, setLocal] = React.useState(String(defaultValue ?? ''));
  const [open, setOpen] = React.useState(false);
  const selected = value === undefined ? local : String(value);
  const details = help ?? description;
  const validationId = validation?.id ?? `${id}-validation`;
  const descriptions = [describedBy, details ? `${id}-description` : '', validation?.message ? validationId : ''].filter(Boolean).join(' ') || undefined;
  const disallowed = (date: Date) => {
    const next = dateValue(date);
    if ((parseDate(min) && next < String(min)) || (parseDate(max) && next > String(max))) return true;
    const interval = step === 'any' ? 1 : Number(step ?? 1);
    const base = parseDate(min) ?? parseDate(String(value ?? defaultValue ?? '')) ?? new Date('1970-01-01T12:00:00');
    return interval > 0 && Math.round((Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()) - Date.UTC(base.getFullYear(), base.getMonth(), base.getDate())) / 86400000) % interval !== 0;
  };
  const choose = (next: string) => {
    if (!native.current || disabled || readOnly) return;
    // Bypass React's value tracker so the existing native onChange contract sees the calendar edit.
    Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value')!.set!.call(native.current, next);
    native.current.dispatchEvent(new Event('input', { bubbles: true }));
    setOpen(false);
    native.current.focus();
  };
  return <div className={className} style={style} data-density={density} data-validation-state={validation?.state} data-oods-component={undefined} data-oods-adapter="DatePicker">
    <Label htmlFor={id}>{label}{required && requiredIndicator !== null ? requiredIndicator ?? <span aria-hidden="true"> *</span> : null}</Label>
    <div className="flex items-center gap-2">
      <Input {...props} ref={native} id={id} type="date" value={value} defaultValue={defaultValue} disabled={disabled} readOnly={readOnly} required={required} min={min} max={max} step={step}
        className={[inputClassName, pickerClassName].filter(Boolean).join(' ')} style={{ ...inputStyle, ...pickerStyle }} data-oods-component={undefined}
        aria-describedby={descriptions} aria-invalid={props['aria-invalid'] ?? (validation?.state === 'error' || undefined)}
        onChange={event => { onChange?.(event); const next = event.currentTarget.value; if (value === undefined) setLocal(next); if (!event.defaultPrevented) { onValueChange?.(next); onUpdate?.(next); } }} />
      <Popover open={open} onOpenChange={next => { if (next && value === undefined) setLocal(native.current?.value ?? ''); setOpen(next); }}>
        <PopoverTrigger disabled={disabled || readOnly} aria-label={`Open calendar for ${typeof label === 'string' ? label : id}`} className="inline-flex h-9 items-center rounded-md border bg-background px-3 text-sm text-foreground">Calendar</PopoverTrigger>
        <PopoverContent className="w-auto p-2">
          <Calendar mode="single" selected={parseDate(selected)} defaultMonth={parseDate(selected)} disabled={disallowed} onSelect={date => { if (date) choose(dateValue(date)); }} />
          <Button type="button" variant="ghost" onClick={() => choose('')}>Clear date</Button>
        </PopoverContent>
      </Popover>
    </div>
    {details ? <p id={`${id}-description`} className="text-sm text-muted-foreground">{details}</p> : null}
    {validation?.message ? <p id={validationId} role={validation.state === 'error' ? 'alert' : 'status'} aria-live={validation.state === 'error' ? 'assertive' : 'polite'}>{validation.message}</p> : null}
  </div>;
});

import * as React from 'react';
import type { TagInputProps } from '@oods/components-react';
import { InputGroup, InputGroupInput } from '@/registry/new-york-v4/ui/input-group';
import { Badge } from '@/registry/new-york-v4/ui/badge';

export const OodsTagInput = React.forwardRef<HTMLFieldSetElement, TagInputProps>(function OodsTagInput(
  { title, label, heading, name, description, subtitle, hint, tags, value, placeholder, children, className, onChange, onValueChange, onUpdate, ...props }, ref,
) {
  const firstText = (...values: Array<string | undefined>) => values.find(value => value?.trim());
  const titleText = firstText(title, label, heading, name) ?? 'Tag Input';
  const details = firstText(description, subtitle, hint);
  const inputId = React.useId();
  const items = (tags ?? []).flatMap(entry => {
    if (entry === undefined || entry === null) return [];
    if (typeof entry === 'object' && !Array.isArray(entry)) {
      const record = entry as Record<string, unknown>;
      const value = ['label', 'name', 'role', 'value', 'id'].map(key => record[key]).find(value => ['string', 'number', 'boolean'].includes(typeof value) && String(value).length > 0);
      return value === undefined ? [] : [String(value)];
    }
    const value = typeof entry === 'object' ? JSON.stringify(entry) : String(entry);
    return value ? [value] : [];
  });
  const authored = React.Children.toArray(children).some(node => typeof node !== 'string' || node.trim().length > 0);
  return <fieldset {...props} ref={ref} className={className} data-oods-component={undefined} data-oods-adapter="TagInput" data-form-type="tag-input">
    <legend className="font-medium">{titleText}</legend>
    {details ? <p className="text-sm text-muted-foreground">{details}</p> : null}
    {authored ? children : <>
      <label htmlFor={inputId} className="text-sm font-medium">Tag</label>
      <InputGroup><InputGroupInput id={inputId} type="text" name="tag" placeholder={firstText(placeholder)} value={value}
        onChange={event => { onChange?.(event); if (!event.defaultPrevented) { onValueChange?.(event.currentTarget.value); onUpdate?.(event.currentTarget.value); } }} /></InputGroup>
      {items.length ? <div data-tag-list="true" className="mt-2 flex flex-wrap gap-1">{items.map((tag, index) => <Badge key={index} variant="secondary" data-tag-item="true">{tag}</Badge>)}</div> : null}
    </>}
  </fieldset>;
});

import * as React from 'react';
import type { StatusSelectorProps } from '@oods/components-react';
import { formatReadOnlyValue } from '@oods/component-contracts';
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from '@/registry/new-york-v4/ui/select';

export const OodsStatusSelector = React.forwardRef<HTMLDivElement, StatusSelectorProps>(function OodsStatusSelector(
  { label, title, help, options, states, value, status, children, className, onChange, onValueChange, onUpdate, ...props }, ref,
) {
  const instance = React.useId();
  const native = React.useRef<HTMLSelectElement>(null);
  const choices = (options ?? states ?? ['draft', 'active', 'inactive']).flatMap(entry => {
    if (entry === undefined || entry === null) return [];
    if (typeof entry === 'object' && !Array.isArray(entry)) {
      const record = entry as Record<string, unknown>;
      const text = (key: string) => typeof record[key] === 'string' && record[key].length > 0 ? record[key] as string : undefined;
      const value = text('value') ?? text('id') ?? text('label') ?? '';
      const label = text('label') ?? text('name') ?? formatReadOnlyValue(value, 'string', true);
      return value || label ? [{ value, label }] : [];
    }
    const value = typeof entry === 'object' ? JSON.stringify(entry) : String(entry);
    return value ? [{ value, label: formatReadOnlyValue(value, 'string', true) }] : [];
  });
  const [local, setLocal] = React.useState(status?.trim() ? status : choices[0]?.value ?? '');
  const selected = value ?? local;
  const empty = '__oods_empty_option__';
  const labelText = [label, title].find(value => value?.trim()) ?? 'Status';
  const authored = React.Children.toArray(children).some(node => typeof node !== 'string' || node.trim().length > 0);
  return <div {...props} ref={ref} className={className} data-oods-component={undefined} data-oods-adapter="StatusSelector" data-summary-type="status-selector">
    {authored ? children : <>
      <label id={`${instance}-label`} htmlFor={instance} className="text-sm font-medium">{labelText}</label>
      <select ref={native} name="status" value={selected} tabIndex={-1} aria-hidden="true" style={{ display: 'none' }}
        onChange={event => { onChange?.(event); if (!event.defaultPrevented) { const next = event.currentTarget.value; if (value === undefined) setLocal(next); onValueChange?.(next); onUpdate?.(next); } }}>
        {choices.length ? choices.map((choice, index) => <option key={index} value={choice.value}>{choice.label}</option>) : <option value="">Select...</option>}
      </select>
      <Select value={selected || empty} onValueChange={next => { if (native.current) { native.current.value = next === empty ? '' : next ?? ''; native.current.dispatchEvent(new Event('change', { bubbles: true })); } }}>
        <SelectTrigger id={instance} aria-labelledby={`${instance}-label`} aria-describedby={help ? `${instance}-help` : undefined}><SelectValue>{choices.find(choice => choice.value === selected)?.label ?? 'Select...'}</SelectValue></SelectTrigger>
        <SelectContent>{choices.length ? choices.map((choice, index) => <SelectItem key={index} value={choice.value || empty}>{choice.label}</SelectItem>) : <SelectItem value={empty}>Select...</SelectItem>}</SelectContent>
      </Select>
    </>}
    {help ? <p id={`${instance}-help`} className="text-sm text-muted-foreground">{help}</p> : null}
  </div>;
});

import * as React from 'react';
import type { CardHeaderProps, HeaderElement } from '@oods/components-react';
import { CardHeader, CardTitle, CardDescription } from '@/registry/new-york-v4/ui/card';

export const OodsCardHeader = React.forwardRef<HTMLElement, CardHeaderProps>(function OodsCardHeader(
  { title, label, text, supporting, supportingText, subtitle, description, level, as, children, className, ...props }, ref,
) {
  const firstText = (...values: Array<string | undefined>) => values.find(value => value?.trim());
  const flatten = (value: React.ReactNode): React.ReactNode[] => React.Children.toArray(value).flatMap(node => React.isValidElement<{ children?: React.ReactNode }>(node) && node.type === React.Fragment ? flatten(node.props.children) : [node]);
  const nodes = flatten(children);
  const authored = nodes.some(node => typeof node !== 'string' && typeof node !== 'number');
  const scalar = authored ? undefined : nodes.join('');
  const heading = scalar?.trim() ? scalar : firstText(title, label, text) ?? 'Card';
  const details = firstText(supporting, supportingText, subtitle, description);
  const Heading = (as && /^h[1-6]$/.test(as) ? as : `h${Number.isFinite(level) ? Math.max(1, Math.min(6, Math.trunc(level!))) : 2}`) as HeaderElement;
  return <header {...props} ref={ref} className={className} data-oods-component={undefined} data-oods-adapter="CardHeader">
    <CardHeader>{authored ? children : <>
      <CardTitle><Heading>{heading}</Heading></CardTitle>
      {details && details.trim() !== heading.trim() ? <CardDescription data-oods-supporting="true">{details}</CardDescription> : null}
    </>}</CardHeader>
  </header>;
});

import * as React from 'react';
import type { PriceBadgeProps } from '@oods/components-react';
import { currencyMinorUnits } from '@oods/component-contracts';
import { Badge } from '@/registry/new-york-v4/ui/badge';

export const OodsPriceBadge = React.forwardRef<HTMLSpanElement, PriceBadgeProps>(function OodsPriceBadge(
  { amountCents, unitAmountCents, minorUnits, amount, unitAmount, currency, currencyCode, label, value, children,
    emphasis = 'subtle', field, amountField, currencyField, intervalField, minorUnitsParameter, ...props }, ref,
) {
  void [field, amountField, currencyField, intervalField, minorUnitsParameter];
  const cents = amountCents ?? unitAmountCents;
  const code = currency ?? currencyCode;
  const price = cents === undefined ? amount ?? unitAmount : cents / currencyMinorUnits(code, minorUnits);
  let formatted: React.ReactNode = value ?? 'Price';
  if (price !== undefined && Number.isFinite(price)) {
    if (!code) formatted = new Intl.NumberFormat(undefined, { maximumFractionDigits: 2 }).format(price);
    else try { formatted = new Intl.NumberFormat(undefined, { style: 'currency', currency: code.toUpperCase() }).format(price); }
    catch { formatted = `${code.toUpperCase()} ${price.toFixed(2)}`; }
  }
  return <Badge {...props} ref={ref} variant={emphasis === 'solid' ? 'default' : 'secondary'}
    data-oods-component={undefined} data-oods-adapter="PriceBadge" data-badge-variant="price" data-price="true" data-currency={code?.toUpperCase()}>
    {label ?? children ?? formatted}
  </Badge>;
});
